mapper.select:
/*commonPopup.zipCodeSearch*/ SELECT ZIP_CODE, /* 우편번호 */ SIDO, /* 시도 */ GUGUN, /* 구군 */ ROAD_NM, /* 도로명 */ BUILDING_NO1||DECODE(BUILDING_NO2, '0', '', '-'||BUILDING_NO2) AS BUILDING_NO, /* 건물 번호 */ BUILDING_NM, /* 건물명 */ NVL(DONG, LAW_DONG) AS DONG, /* 동 */ JIBUN1||DECODE(JIBUN2, '0', '', '-'||JIBUN2) AS JIBUN, /* 지번 */ BUILDING_MNG_NO /* 관리번호 */ FROM ICOMPOST POST WHERE 1=1 AND SIDO = #{st_si_select_nm}
AND GUGUN IS NULL
AND GUGUN IS NOT NULL
AND GUGUN = #{st_gu_select_nm}
AND ROAD_NM = #{st_search1} AND TO_CHAR(BUILDING_NO1) = #{st_search2}
AND NVL(DONG, LAW_DONG) LIKE '%'||#{st_search1}||'%' AND JIBUN1||DECODE(JIBUN2, 0, '', JIBUN2) LIKE REPLACE(#{st_search2},'-')||'%'
AND BUILDING_NM LIKE '%'||#{st_search1}||'%'
AND (upper(ROAD_NM) like '%'||#{st_search1}||'%' or upper(NVL(DONG, LAW_DONG)) LIKE '%'||#{st_search1}||'%' or upper(BUILDING_NM) LIKE '%'||#{st_search1}||'%')
AND (JIBUN1||DECODE(JIBUN2, 0, '', JIBUN2) LIKE REPLACE(#{st_search2},'-')||'%' or BUILDING_NO1||DECODE(building_no2, 0, '', BUILDING_NO2) LIKE REPLACE( #{st_search2} /**P*/ ,'-')||'%')
ORDER BY ZIP_CODE, SIDO, GUGUN, ROAD_NM, BUILDING_NO


   /*commonPopup.deptCodeAdminPop*/
		SELECT										        
				CODE, 								 
				TEXT1, 							 
				TEXT2, 							 
				(SELECT COUNT(*) FROM ICOMLUSR WHERE COM_CODE=COMPANY_CODE AND DEPARTMENT=CODE AND STATUS <> 'D') AS DEPT_USER_COUNT	 
		  FROM ICOMCOD2 							 



		    	WHERE COMPANY_CODE IN (
		 			SELECT DISTINCT CODE2 FROM ICOMCOD3 WHERE TYPE = 'TGCM' AND CODE1 = #{st_user_id} AND FLAG = 'Y'
				)				


		    	WHERE COMPANY_CODE = #{com_code}		    



	       AND UPPER(TEXT1) LIKE UPPER( '%'||#{st_req_dept_name}||'%')


		AND CODE LIKE '%'||#{st_req_dept_code}||'%'		 	 			


		AND (TYPE_FLAG = 'A' OR TYPE_FLAG = #{st_dept_type})

		AND TYPE= #{st_type}
	/* SLOGIC-BEGIN (1010_02) */		


				AND TEXT4 = 'PROFIT'	


				AND TEXT4 = 'COST'	


	/* SLOGIC-END */
	ORDER BY COMPANY_CODE, CODE

/*commonPopup.agentRegMakerCodePop*/ SELECT CODE , TEXT1 , TEXT2 , NVL(TEXT3, '') TEXT3 , NVL(TEXT4, '') TEXT4 , TEXT5 , NVL(TEXT8, '') TEXT8 , F_GET_MAKER_USE_YN(CODE, #{st_buyer_code}) AS FLAG FROM ICOMCOD1 WHERE TYPE = 'M104' AND ( TEXT1 LIKE UPPER('%'|| #{st_del_name} ||'%')
OR UPPER(TEXT8) LIKE UPPER('%'|| #{st_del_name} ||'%')
) AND FLAG = 'Y' ORDER BY VALUE1

/*commonPopup.vocUserSelectPop*/ SELECT L.USER_ID, --[0] L.USER_NAME_LOC, --[1] L.DEPARTMENT, --[2] (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = L.COM_CODE AND CODE = L.DEPARTMENT AND TYPE = 'C001') AS DEPT_NAME --[3] FROM ICOMLUSR L WHERE 1=1 AND L.COM_CODE LIKE '%'||#{com_code}||'%'
AND L.USER_ID LIKE '%'||#{user_id}||'%'
AND L.USER_NAME_LOC LIKE '%'||#{user_name_loc}||'%'
AND L.DEPARTMENT =#{dept_code}
AND L.STATUS <> 'D' ORDER BY L.USER_NAME_LOC

/*commonPopup.companyCodePop*/
SELECT X.COM_CODE, X.COM_NAME, X.CLEVEL, X.COMG_CODE, DECODE(SUBSTR(X.COM_CODE,7,1),'G','1','2') AS SEQ FROM ( SELECT COMORG_CODE AS COM_CODE, COMORG_NAME AS COM_NAME, COMORG_LEVEL AS CLEVEL, COMORG_CODE AS COMG_CODE FROM BYCAORGL WHERE COMORG_LEVEL='1' AND VALID_FLAG='Y' AND COMORG_NAME LIKE '%'||#{COM_NAME_LOC}||'%' UNION ALL SELECT COM_CODE AS COM_CODE , COM_NAME_LOC AS COM_NAME, BYCA_COMORG_LEVEL AS CLEVEL, BYCA_COMORG_CODE AS COMG_CODE FROM ICOMCMPY WHERE STATUS IN ('C', 'R') AND BUSINESS_COND in (#{COM_TYPE},'M') AND COM_NAME_LOC LIKE '%'||#{COM_NAME_LOC}||'%'
) X ORDER BY X.COMG_CODE ,SEQ,X.COM_CODE



		/*commonPopup.positionCodePop*/

 			   SELECT TYPE,CODE, COMPANY_CODE,TEXT1, TEXT2,TEXT3,TEXT4,VALUE1,FLAG,ADD_DATE  
               FROM ICOMCOD2  
               WHERE COMPANY_CODE = #{com_code}
               AND TYPE  like  '%'||#{type}||'%'


/*commonPopup.comCode2PopSearch*/
	SELECT
	 COD2.CODE
	 ,COD2.TEXT1
	 ,COD2.TEXT2
	FROM ICOMCOD2 COD2
	WHERE  COMPANY_CODE = #{st_buyer}
	AND TYPE = #{st_type}



	AND COD2.CODE = #{st_code}


	AND UPPER(COD2.TEXT1) LIKE UPPER('%'||#{st_text}||'%')


	AND COD2.TEXT4 = #{st_text4}


	AND FLAG = 'Y'


	ORDER BY COD2.CODE


/*commonPopup.comCode3PopSearch*/
	SELECT
	 COD3.CODE1
	 ,COD3.CODE2
	 ,COD3.TEXT1
	 ,COD3.TEXT2
	FROM ICOMCOD3 COD3
	WHERE BUYER = #{st_buyer}
	AND TYPE = #{st_type}
	AND FLAG = 'Y'


	AND COD3.CODE1 = #{st_code1}


	AND COD3.CODE2 = #{st_code2}


	AND UPPER(COD3.TEXT1) LIKE UPPER('%'||#{st_text1}||'%')


	AND UPPER(COD3.TEXT2) LIKE UPPER('%'||#{st_text2}||'%')

/*commonPopup.comCode4PopSearch*/ SELECT COD4.CODE1, COD4.CODE2, COD4.TEXT1, COD4.TEXT2, COD4.TEXT3, COD4.TEXT4, COD4.TEXT5, COD4.TEXT6, COD4.TEXT7 FROM ICOMCOD4 COD4 WHERE BUYER = #{st_buyer} AND TYPE = #{st_type} AND FLAG = 'Y'
AND COD4.CODE1 = #{st_code1}
AND COD4.CODE2 = #{st_code2}
AND UPPER(COD4.TEXT1) LIKE UPPER('%'||#{st_text1}||'%')
AND UPPER(COD4.TEXT2) LIKE UPPER('%'||#{st_text2}||'%')
AND UPPER(COD4.TEXT3) LIKE UPPER('%'||#{st_text3}||'%')
AND UPPER(COD4.TEXT4) LIKE UPPER('%'||#{st_text4}||'%')
AND UPPER(COD4.TEXT5) LIKE UPPER('%'||#{st_text5}||'%')
AND UPPER(COD4.TEXT6) LIKE UPPER('%'||#{st_text6}||'%')
AND UPPER(COD4.TEXT7) LIKE UPPER('%'||#{st_text7}||'%')


	/*commonPopup.commonTwoSearchList*/
        SELECT  TYPE, CODE, TEXT1, TEXT3 FROM ICOMCOD1
        WHERE  TYPE = #{SEARCH1}
			AND TEXT2 = #{SEARCH2}


	/*commonPopup.commonVocClaimTypeList*/
        SELECT  CODE || '@@' || TEXT3 AS CODE, TEXT1 FROM ICOMCOD1
        WHERE  TYPE = #{SEARCH1}
			AND TEXT2 = #{SEARCH2}



	/*commonPopup.commonIcomcod1List*/

               SELECT CODE, TEXT1 , TEXT2
			      FROM ICOMCOD1 
			    WHERE TYPE= #{type}

/*commonPopup.getIcomcod1WhereList*/
SELECT C.CODE , C.TEXT1 , C.TEXT2 FROM ICOMCOD1 C WHERE C.TYPE= #{type} AND C.FLAG = 'Y'
AND C.TEXT1 LIKE '%'||#{st_text}||'%' ORDER BY C.ADD_DATE



	/*commonPopup.getIcomcod2List*/

               SELECT CODE, TEXT1 , TEXT2
			      FROM ICOMCOD2 
			    WHERE COMPANY_CODE = #{com_code}
			    AND TYPE= #{type}
			    AND FLAG = 'Y'


		AND UPPER(TEXT1) LIKE '%'||UPPER(#{st_text})||'%'

/*commonPopup.icomcmpyPop*/ SELECT X.COM_CODE, X.COM_NAME AS COM_NAME_LOC, X.CLEVEL, X.COMG_CODE, DECODE(SUBSTR(X.COM_CODE,7,1),'G','1','2') AS SEQ , X.AGENT_OPEN_FLAG , X.CEO_NAME_LOC , X.GR_EMP_TEL , X.BUSINESS_ITEMS , X.GR_EMP_NM , X.DSS_YN , X.DSS_MSG , X.IRS_NO , X.BYEX_YN , X.LOGISTICS_CENTER_CNT FROM (
/* 김승우 팀장님 요청 : 2014.10.22 - 김지현 차장과 통화 후 추가 내용 */ SELECT COMORG_CODE AS COM_CODE, COMORG_NAME AS COM_NAME, COMORG_LEVEL AS CLEVEL, COMORG_CODE AS COMG_CODE , (SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = A.COMORG_CODE) AS AGENT_OPEN_FLAG , '' AS CEO_NAME_LOC , '' AS GR_EMP_TEL , '' AS BUSINESS_ITEMS , '' AS GR_EMP_NM , '' AS DSS_YN , '' AS DSS_MSG , '' AS BYEX_YN , '' AS IRS_NO , 0 AS LOGISTICS_CENTER_CNT FROM BYCAORGL A WHERE COMORG_LEVEL='1' AND VALID_FLAG='Y' AND UPPER(COMORG_NAME) LIKE '%'||UPPER(#{COM_NAME_LOC})||'%'
AND COMORG_CODE IN ( SELECT BYCA_COMORG_CODE FROM ICOMCMPY CMPY WHERE BUSINESS_COND IN ('B','M') AND STATUS IN ('R','C') AND COM_CODE IN (SELECT CMPY.COM_CODE FROM ICOMCOD3 COD3 WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= 'ALL' AND COD3.CODE2 = #{st_session_id} UNION ALL SELECT MNG.BUYER FROM ICOMCOD3 COD3, MIS_BUYER_MNG MNG WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= MNG.KEP_DEPT AND COD3.CODE2 = #{st_session_id} AND MNG.YEAR = TO_CHAR(SYSDATE,'YYYY') AND MNG.STATUS = 'C' UNION ALL SELECT BUYER FROM MIS_BUYER_MNG WHERE YEAR = TO_CHAR(SYSDATE,'YYYY') AND STATUS = 'C' AND KEP_USER_ID = #{st_session_id} UNION ALL SELECT COD.CODE1 FROM ICOMCOD3 COD , ICOMCMPY CMPY WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'CMPY' AND COD.CODE1 = CMPY.COM_CODE AND COD.CODE2 = #{st_session_id} AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN TEXT2 AND TEXT3 ) )
UNION ALL
SELECT COM_CODE AS COM_CODE , COM_NAME_LOC AS COM_NAME, BYCA_COMORG_LEVEL AS CLEVEL, BYCA_COMORG_CODE AS COMG_CODE , AGENT_OPEN_FLAG , A.CEO_NAME_LOC , NVL(A.GR_EMP_TEL, A.TEL_NO) AS GR_EMP_TEL , A.BUSINESS_ITEMS , NVL(A.GR_EMP_NM, A.CEO_NAME_LOC) AS GR_EMP_NM , F_GET_DSS_CHK(#{st_buyer_code},A.COM_CODE,0) AS DSS_YN , F_GET_DSS_CHK(#{st_buyer_code},A.COM_CODE,1) AS DSS_MSG , (SELECT DECODE(COUNT(COD2.CODE),0,'N','Y') FROM ICOMCOD2 COD2 WHERE COD2.TYPE = 'BYEX' AND COD2.COMPANY_CODE = 'KRKORE0001' AND COD2.CODE = A.COM_CODE) AS BYEX_YN , A.IRS_NO , (SELECT COUNT(0) FROM ICOMCOD1 WHERE TYPE = 'HUB' AND FLAG ='Y' AND CODE = A.COM_CODE ) AS LOGISTICS_CENTER_CNT FROM ICOMCMPY A WHERE STATUS IN ('C', 'R') AND BUSINESS_COND in (#{BUSINESS_COND}) AND UPPER(COM_NAME_LOC) LIKE '%'||UPPER(#{COM_NAME_LOC})||'%'
AND A.COM_CODE IN ( SELECT A.COM_CODE FROM ICOMCOD3 COD3 WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= 'ALL' AND COD3.CODE2 = #{st_session_id} UNION ALL SELECT MNG.BUYER FROM ICOMCOD3 COD3, MIS_BUYER_MNG MNG WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= MNG.KEP_DEPT AND COD3.CODE2 = #{st_session_id} AND MNG.YEAR = TO_CHAR(SYSDATE,'YYYY') AND MNG.STATUS = 'C' UNION ALL SELECT BUYER FROM MIS_BUYER_MNG WHERE YEAR = TO_CHAR(SYSDATE,'YYYY') AND STATUS = 'C' AND KEP_USER_ID = #{st_session_id} UNION ALL SELECT COD.CODE1 FROM ICOMCOD3 COD , ICOMCMPY CMPY WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'CMPY' AND COD.CODE1 = CMPY.COM_CODE AND COD.CODE2 = #{st_session_id} AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN TEXT2 AND TEXT3 )
AND CREDIT_STATUS <> 'N'
) X ORDER BY X.COMG_CODE ,SEQ,X.COM_CODE

/*commonPopup.catalogDetailPop*/ SELECT TRIM(NVL((SELECT DISTINCT IMGFILE_DIR FROM CMSCATLG WHERE CMS_CATLG_ID = BT.CMS_CATLG_ID),BT.IMGFILE_DIR)) AS IMGFILE_DIR, TRIM(NVL((SELECT DISTINCT IMGFILE_NAME FROM CMSCATLG WHERE CMS_CATLG_ID = BT.CMS_CATLG_ID),BT.IMGFILE_NAME)) AS IMGFILE_NAME, BT.CATEGORY_TEXT, BT.CATEGORY_NO, DT.BUYER_ITEM_NO||DECODE(DT.BUYER_ITEM_NO,DT.SELLER_ITEM_NO,NULL,'['||DT.SELLER_ITEM_NO||']') AS BUYER_ITEM_NO, DT.DESCRIPTION, DT.SPECIFICATION, BT.UNIT_MEASURE, DT.DELIVERY_LT, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND DT.ORIGIN_CODE = CODE) AS ORIGIN, BT.MAKER_NAME, BT.REMARK, DT.UNIT_PRICE, -- 매출 고객사 DT.LIST_PRICE, -- 매입 협력사 DECODE(NVL(DT.AGENT,'MULTI'),'MULTI','복수협력사입니다','+','복수협력사입니다', DECODE((SELECT MAX(AGENT_OPEN_FLAG) FROM ICOMCMPY WHERE COM_CODE = DT.BELOW_COMORG_CODE),'N','코리아e플랫폼(주)', (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = DT.AGENT))) AS AGENT_TEXT, DECODE(BT.STATUS,'D','삭제',DECODE(DT.STATUS,'D','삭제',DECODE(BT.PRODUCT_CLOSE_FLAG,'N','승인','Y','단종'))) AS STATUS_TEXT, TRIM(BT.IMAGE_KEY) AS IMAGE_KEY, (SELECT COUNT(*) FROM ICOMATCH WHERE DOC_NO=BT.IMAGE_KEY) AS ATTACH_CNT, DECODE(TRIM(BT.MSDS_NO),'MS99999999', '', TRIM(BT.MSDS_NO)) AS MSDS_NO, BT.ITEM_DETAIL_DESC, BT.KEP_MAKER_PART_NO, DT.PROCESS_TYPE, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M034' AND CODE = DT.PROCESS_TYPE AND FLAG = 'Y') AS PROCESS_TYPE_NAME, F_GET_LOGISTICS_FEE_INFO(DT.BELOW_COMORG_CODE, DT.BUYER_ITEM_NO, DT.PROCESS_TYPE, DT.AGENT, 0,'02', DT.ORIGIN_AGENT) AS LOGISTICS_RATE, F_GET_LOGISTICS_FEE_INFO(DT.BELOW_COMORG_CODE, DT.BUYER_ITEM_NO, DT.PROCESS_TYPE, DT.AGENT, 0,'03', DT.ORIGIN_AGENT) AS LOGIS_RATE_STATUS, DT.MIN_ORDER_QTY, DT.PUR_UNIT_QTY FROM ICOMBYIT BT, ICOMCQDT DT WHERE BT.BUYER = #{BUYER} AND BT.BUYER_ITEM_NO = #{BUYER_ITEM_NO} AND BT.BUYER = DT.BUYER AND BT.BUYER_ITEM_NO = DT.BUYER_ITEM_NO
AND DT.CONTRACT_NO = #{CONTRACT_NO}
AND DT.CONTRACT_SEQ = #{CONTRACT_SEQ}

/*commonPopup.catalogDetailPop_v2*/
SELECT
TRIM(NVL((SELECT DISTINCT IMGFILE_DIR FROM CMSCATLG WHERE CMS_CATLG_ID = BT.CMS_CATLG_ID),BT.IMGFILE_DIR)) AS IMGFILE_DIR, TRIM(NVL((SELECT DISTINCT IMGFILE_NAME FROM CMSCATLG WHERE CMS_CATLG_ID = BT.CMS_CATLG_ID),BT.IMGFILE_NAME)) AS IMGFILE_NAME, BT.CATEGORY_TEXT, BT.CATEGORY_NO, DT.BUYER_ITEM_NO||DECODE(DT.BUYER_ITEM_NO,DT.SELLER_ITEM_NO,NULL,'['||DT.SELLER_ITEM_NO||']') BUYER_ITEM_NO, DT.DESCRIPTION, DT.SPECIFICATION, BT.UNIT_MEASURE, DT.DELIVERY_LT, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND DT.ORIGIN_CODE = CODE) ORIGIN, BT.MAKER_NAME, BT.REMARK, DT.UNIT_PRICE, -- 매출 고객사 DT.LIST_PRICE, -- 매입 협력사
DECODE(NVL(DT.AGENT,'MULTI'),'MULTI','복수협력사입니다','+','복수협력사입니다', DECODE((SELECT MAX(AGENT_OPEN_FLAG) FROM ICOMCMPY WHERE COM_CODE = DT.BELOW_COMORG_CODE) ,'N','코리아e플랫폼(주)',
(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = DT.AGENT)
)) AGENT_TEXT,
DECODE(BT.STATUS,'D','삭제',DECODE(DT.STATUS,'D','삭제', DECODE(BT.PRODUCT_CLOSE_FLAG,'N','승인','Y','단종'))) AS STATUS_TEXT ,
TRIM(BT.IMAGE_KEY) AS IMAGE_KEY, (SELECT COUNT(*) FROM ICOMATCH WHERE DOC_NO=BT.IMAGE_KEY) AS ATTACH_CNT
,BT.ITEM_DETAIL_DESC ,BT.KEP_MAKER_PART_NO ,DT.PROCESS_TYPE ,(SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M034' AND CODE = DT.PROCESS_TYPE AND FLAG = 'Y') AS PROCESS_TYPE_NAME ,F_GET_LOGISTICS_FEE_INFO(DT.BELOW_COMORG_CODE, DT.BUYER_ITEM_NO, DT.PROCESS_TYPE, DT.AGENT, 0,'02') AS LOGISTICS_RATE ,F_GET_LOGISTICS_FEE_INFO(DT.BELOW_COMORG_CODE, DT.BUYER_ITEM_NO, DT.PROCESS_TYPE, DT.AGENT, 0,'03') AS LOGIS_RATE_STATUS ,DT.MIN_ORDER_QTY ,DT.PUR_UNIT_QTY ,BT.MSDS_NO FROM ICOMBYIT BT, ICOMCQDT DT WHERE BT.BUYER = #{BUYER} AND BT.BUYER_ITEM_NO = #{BUYER_ITEM_NO} AND BT.BUYER = DT.BUYER AND BT.BUYER_ITEM_NO = DT.BUYER_ITEM_NO
AND DT.CONTRACT_NO =#{CONTRACT_NO}
AND DT.CONTRACT_SEQ = #{CONTRACT_SEQ}

/*commonPopup.approvalHumanEditPop_v2*/ SELECT LUSR.USER_ID, LUSR.USER_NAME_LOC || '(' || LUSR.USER_ID || ')' AS USER_NAME_LOC, DEPT.TEXT1 AS DEPARTMENT, POSI.TEXT1 AS POSITION FROM ICOMLUSR LUSR LEFT JOIN ICOMCOD2 DEPT ON DEPT.COMPANY_CODE = LUSR.COM_CODE AND DEPT.TYPE = 'C001' AND DEPT.CODE = LUSR.DEPARTMENT LEFT JOIN ICOMCOD2 POSI ON POSI.COMPANY_CODE = LUSR.COM_CODE AND POSI.TYPE = 'C003' AND POSI.CODE = LUSR.POSITION WHERE LUSR.STATUS IN ('C', 'R') AND LUSR.COM_CODE = #{COMPANY} AND NVL(LUSR.OFFICE_YN, 'N') != 'Y'
AND ( LUSR.USER_NAME_LOC LIKE '%' || #{USER_NAME_LOC} || '%' OR DEPT.TEXT1 LIKE '%' || #{USER_NAME_LOC} || '%' )
AND LUSR.USER_ID != #{USER_ID}



/*commonPopup.catePriceHistoryPop*/

SELECT  
	CONTRACT_NO,        --[01]
	CONTRACT_SEQ,       --[02]
	BUYER_ITEM_NO,      --[03]
	BUYER,              --[00]
	UNIT_PRICE,         --[04]
	MIN(CHANGE_DATE) CHANGE_DATE   --[05]
FROM ICOMCQEP  
	WHERE BUYER = #{byca_comorg_code}	  
	AND CONTRACT_NO = #{contract_no}	  
	AND CONTRACT_SEQ = #{contract_seq}	  
	AND BUYER_ITEM_NO = #{buyer_item_no}	  
GROUP BY BUYER,CONTRACT_NO, CONTRACT_SEQ,BUYER_ITEM_NO,UNIT_PRICE  
ORDER BY 6


/* commonCoCoLocationDetailPop */
SELECT  C.CODE,
		    C.TEXT1,
		    C.TEXT2
  FROM  ICOMCOD2 C
WHERE  C.COMPANY_CODE = #{st_com_code}
	AND C.TYPE = 'C001'
	AND C.CODE = #{st_dept}

/* commonCoCoNationCodePop */ SELECT CODE, TEXT1, TEXT2 FROM ICOMCOD1 WHERE TYPE='M001'
AND (TEXT1 LIKE '%'||#{country_search}||'%' OR TEXT2 LIKE '%'||#{country_search}||'%')
ORDER BY TEXT2

/* commonPopup.getCommonCoCoGoodsDlvyClssifyPop */ SELECT CODE, TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M034' AND FLAG = 'Y'
AND CODE IN ('0','2')
ORDER BY CODE

/* commonPopup.commonCoCoLogisticCenterCatalogPop */ SELECT /*+USE_NL(CQDT STCK) INDEX(STCK SYS_C0053026)*/ CQDT.BUYER_ITEM_NO, CQDT.DESCRIPTION, CQDT.MAKER_NAME, CQDT.LIST_PRICE, STCK.AVAIL_QTY, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = CQDT.AGENT) AS AGENT_NAME, CQDT.AGENT, DECODE(CQDT.PROCESS_TYPE,'1','재고상품','3','VMI상품') AS PROCESS_TEXT, CQDT.SPECIFICATION, CQDT.UNIT_MEASURE, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE='M001' AND CODE =CQDT.ORIGIN_CODE) AS ORIGIN_TEXT, STCK.LOCATION_ID, CQDT.PROCESS_TYPE, STCK.WAREHOUSE_CODE, DECODE(CQDT.PROCESS_TYPE,'1','재고','3','VMI') AS PROCESS_NAME, CQDT.ORIGIN_CODE AS ORIGIN_CODE, CQDT.MAKER_PART_NO AS MAKER_PART_NO, BYIT.CATEGORY_NO AS STD_CATEG_ID, BYCA.CATEG_PATH AS CATEG_PATH, BYCA.CATEG_NAME AS CATEG_NAME, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'W001' AND TEXT1 = STCK.WAREHOUSE_CODE AND TEXT4 = 'B' ) WAREHOUSE_NAME, SUBSTR(STCK.WAREHOUSE_CODE,1,6)||LPAD(TO_NUMBER(SUBSTR(STCK.WAREHOUSE_CODE,7,4))+1,4,0) WAREHOUSE_CODE_AGENT FROM ICOMCQDT CQDT, WMSSTCK STCK , ICOMBYIT BYIT, ICOMBYCA BYCA WHERE CQDT.BUYER = STCK.WAREHOUSE_CODE AND CQDT.BUYER_ITEM_NO = STCK.STDCATLG_ID AND CQDT.STATUS <> 'D' AND BYIT.STATUS <> 'D' AND BYCA.STATUS(+) <> 'D' AND CQDT.BUYER = BYIT.BUYER AND CQDT.BUYER_ITEM_NO = BYIT.BUYER_ITEM_NO AND BYIT.BUYER = BYCA.COM_CODE(+) AND BYIT.CATEGORY_NO = BYCA.STD_CATEG_ID(+) AND CQDT.BUYER = #{st_warehouse_code}
AND CQDT.AGENT = #{st_agent_code}
AND CQDT.BUYER_ITEM_NO LIKE '%' || #{st_stdcatlg_id} || '%'
AND CQDT.DESCRIPTION LIKE '%' || #{st_description} || '%'
AND CQDT.SPECIFICATION LIKE '%' || #{st_specification} || '%'
AND CQDT.PROCESS_TYPE = #{st_type}

/* commonPopup.commonCoCoUserChoice2Pop */ SELECT A.USER_ID, A.USER_NAME_LOC, B.COM_NAME_LOC, (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = A.COM_CODE AND CODE = A.DEPARTMENT) AS DEPARTMENT_NAME, A.PHONE_NUMBER, A.EMAIL, DECODE(A.USER_TYPE,'M','마스터','A','ADMIN','U','일반','KEP') AS GUBUN, A.COM_CODE, A.DEPARTMENT, A.USER_TYPE FROM ICOMLUSR A, ICOMCMPY B WHERE A.COM_CODE = B.COM_CODE AND A.STATUS IN ('C','R') AND B.STATUS IN ('C','R')
AND A.USER_NAME_LOC LIKE '%' || #{st_user_name} || '%'
AND B.COM_NAME_LOC LIKE '%' || #{com_name} || '%'
AND B.COM_CODE = #{com_code}
ORDER BY 2,1

/* commonPopup.commonCoCoOrderDepartmentSearchPop */ SELECT DP.CODE, DP.TEXT1, DP.TEXT2 FROM ICOMCOD2 DP , ICOMCOD2 PS WHERE DP.COMPANY_CODE = #{com_code} AND DP.COMPANY_CODE = PS.COMPANY_CODE AND DP.TYPE='C001' AND PS.TYPE='C004' AND DP.CODE = PS.CODE
AND UPPER(DP.TEXT1) LIKE UPPER('%' || #{req_dept_name} || '%')
ORDER BY DP.CODE

/* commonPopup.commonCoCoBudgetDepartmentCodePop */ SELECT A.CODE, A.TEXT1, ( SELECT COUNT(code2) FROM ICOMCOD3 WHERE BUYER = A.COMPANY_CODE AND CODE1 = A.CODE AND TYPE = 'DTOD' ) AS CNT FROM ICOMCOD2 A WHERE A.COMPANY_CODE = #{st_com_code} AND A.TYPE='C001'
AND (A.TYPE_FLAG = 'A' OR A.TYPE_FLAG = #{st_dept_type})
AND UPPER(A.TEXT1) LIKE UPPER('%' || #{st_bdgt_dept_name} || '%')

/* commonPopup.commonCoCoBudgetDepartmentCodeDiffPop */ SELECT CODE, TEXT1, ( SELECT COUNT(code2) FROM ICOMCOD3 WHERE BUYER = A.COMPANY_CODE AND CODE1 = A.CODE AND TYPE = 'DTOA' ) AS CNT FROM ICOMCOD2 A, ( SELECT CODE2 AS DEPT_CODE FROM ICOMCOD3 WHERE BUYER = #{st_com_code} AND TYPE = 'DTOD' GROUP BY CODE2 ) B WHERE A.COMPANY_CODE = #{st_com_code} AND A.TYPE='C001' AND A.CODE = B.DEPT_CODE
AND (A.TYPE_FLAG = 'A' OR A.TYPE_FLAG = #{st_dept_type})
AND UPPER(A.TEXT1) LIKE UPPER('%' || #{st_bdgt_account_name} || '%')

/* commonPopup.commonCoCoExistingCatalogPop */ SELECT /*+USE_NL(B A) INDEX(A ICOMBYIT_PK) INDEX(B ICOMCQDT_03)*/ B.BUYER_ITEM_NO, --[00] B.UNIT_PRICE, --[01] B.LIST_PRICE, --[02] DECODE(B.UNIT_PRICE,0,0,ROUND(((B.UNIT_PRICE - B.LIST_PRICE)/B.UNIT_PRICE) *100,1)) AS RATE, --[03] B.MAKER_NAME, --[04] (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = B.ORIGIN_CODE) AS ORIGIN_TEXT, --[05] (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = B.AGENT) AS AGENT_TEXT, --[06] B.DESCRIPTION, --[07] B.SPECIFICATION, --[08] B.ORIGIN_CODE, --[09] B.AGENT, --[10] B.CONTRACT_NO, --[11] B.CONTRACT_SEQ, --[12] B.BUYER, --[13] DECODE(A.STATUS,'D','D',DECODE(B.STATUS,'D','D', DECODE(A.PRODUCT_CLOSE_FLAG,'N','N','Y','Y','T','Y'))) AS STATUS_TEXT, --[14] B.MAKER_CODE, -- [15] B.UNIT_MEASURE, -- [16] B.PROCESS_TYPE, B.ORIGIN_AGENT FROM ICOMBYIT A, ICOMCQDT B WHERE B.BUYER = #{st_byca_comorg_code} AND A.BUYER = B.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.PRODUCT_CLOSE_FLAG NOT IN ('S','G')
AND A.BUYER_ITEM_NO LIKE #{st_buyer_item_no} || '%'
AND B.DESCRIPTION LIKE '%' || #{st_description_loc} || '%'
AND B.SPECIFICATION LIKE '%' || #{st_specification} || '%'
AND B.AGENT = #{st_session_com_code}
ORDER BY 1 ORDER BY 8 ORDER BY 9 ORDER BY 5 ORDER BY 7 ORDER BY 15


