/*commonPopup.masterMpSoAgntcmpyTypePop*/
	SELECT  DISTINCT AGENT,
				(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = AGENT) AS AGENT_NAME
	FROM ICOMCQDT
	WHERE BUYER = #{st_wms_code}


			AND PROCESS_TYPE = #{st_process_type}


/*commonPopup.selectCheckedPoAgentDeptList*/
	SELECT DECODE(COUNT(*), 0, 'FALSE', 'TRUE')
	  FROM ICOMPOHD A
	 WHERE A.AGENT= #{st_com_code}  --session com_code
	   AND A.PO_CREATE_DATE >= #{st_from_date}
	   AND A.STATUS<>'D'
	   AND A.BUYER IN (
			SELECT DISTINCT BUYER FROM MIS_BUYER_MNG
			WHERE STATUS = 'C' AND YEAR = SUBSTR(TO_CHAR(SYSDATE,'YYYYMMDD'),0,4)
			AND KEP_DEPT = #{st_dept_code}
		)

/*commonPopup.getZcodeList*/ SELECT A.ZCODE ,A.GONGJE , MAX(A.BCODE) AS BCODE , '('||DECODE(MAX(A.GONGJE), '1', '수', '2', '운', 'X')||')'||MAX(B.TEXT1) AS ZNAME , MAX(A.MAKTX) AS MAKTX , F_COWAY_BUDAM_AMT(A.MATNR, A.ZCODE, DECODE(#{st_buyer }, 'KRCOWA0002', #{st_ji_gubun }, 'KRCOWA0003',#{st_sin_gubun }, 'KRCOWA0007', #{st_ji_gubun }, 'KRCOWA0008', #{st_ji_gubun })) AS COWAY_BUDAM_PRICE , MAX(A.GONGJE) AS GONGJE , TO_CHAR(MAX(A.LMENGE)) AS LMENGE , TO_CHAR(MAX(A.SMENGE)) AS SMENGE FROM COWAY_BYIT A, ICOMCOD2 B WHERE 1=1 AND A.ZCODE = B.CODE AND A.CLS = DECODE(#{st_buyer } ,'KRCOWA0002', 'CL','KRCOWA0003' ,'CS','KRCOWA0007','CH','KRCOWA0008','CW') AND A.MATNR = #{st_item_no } AND B.COMPANY_CODE = #{st_buyer } AND B.TYPE = 'Z019'
AND A.GONGJE IN (SELECT DECODE(ROLE_GBN,'W','2','S','1') ROLE_GBN FROM( SELECT CODE ,TEXT2 AS ROLE_GBN FROM ICOMCOD2 COD2 WHERE TYPE = 'C007' AND COMPANY_CODE= #{st_buyer } AND COD2.CODE = #{userId } UNION ALL SELECT CODE ,TEXT3 AS ROLE_GBN FROM ICOMCOD2 COD2 WHERE TYPE = 'C007' AND COMPANY_CODE= #{st_buyer } AND COD2.CODE = #{userId } ) X WHERE X.ROLE_GBN IS NOT NULL )
GROUP BY A.ZCODE, A.MATNR,A.GONGJE ORDER BY A.ZCODE, A.MATNR,A.GONGJE

/* commonPopup.commonCoCoAccountPop_v2 */ SELECT CODE , TEXT1 FROM ICOMCOD2 WHERE 1=1 AND COMPANY_CODE = #{st_com_code} AND TYPE = 'Z014'
AND UPPER(TEXT1) LIKE UPPER('%' || #{st_account_name} || '%')
AND (UPPER(CODE) LIKE UPPER('%' || #{st_keyword} || '%') OR UPPER(TEXT1) LIKE UPPER('%' || #{st_keyword} || '%'))

/* commonPopup.getBudegtOrderAmtPop */ SELECT XX.BUDGET_DEPT_NM , SUM(XX.CART_QTY * XX.TARGET_PRICE) AS ORDER_PRICE FROM(
SELECT A.BUDGET_DEPT , (SELECT TEXT1 FROM ICOMCOD2 COD2 WHERE COD2.COMPANY_CODE = A.BUYER AND COD2.CODE = A.BUDGET_DEPT AND COD2.TYPE = 'C001') AS BUDGET_DEPT_NM , DECODE(B.FIXED_PRICE_FLAG,'N',NVL(A.UNIT_PRICE,0),NVL(C.TARGET_PRICE,0)) TARGET_PRICE , DECODE(A.CART_QTY,'0','1',NVL(A.CART_QTY,1)) CART_QTY FROM ICOMCART A, ICOMBYIT B, ICOMCQDT C ,ICOMCMPY CM WHERE A.BYIT_COMORG_CODE = B.BUYER AND B.BUYER = C.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.BUYER = #{st_buyer} AND A.USER_ID = #{st_userid}
AND C.BUYER_ITEM_NO||C.CONTRACT_NO||C.CONTRACT_SEQ||A.SEQ IN
#{item}
AND A.USE_FLAG = 'C' AND A.BUYER = CM.COM_CODE AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND B.PRODUCT_CLOSE_FLAG = 'N' AND A.CONTRACT_NO = C.CONTRACT_NO AND A.CONTRACT_SEQ = C.CONTRACT_SEQ ) XX GROUP BY XX.BUDGET_DEPT_NM ORDER BY XX.BUDGET_DEPT_NM


/*commonPopup.commonQuotDetailInfoPop2*/
	SELECT	BUYER_ITEM_NO,
			REPLACE(DESCRIPTION,'"','') AS DESCRIPTION,
			REPLACE(SPECIFICATION,'"','') AS SPECIFICATION,
			F_GET_RE_STTS(BUYER, QUOTATION_NO,QUOTATION_SEQ,REVISION,0) AS SOURCING_STATUS
	FROM KEPRQDT
	WHERE BUYER = #{st_buyer}
	AND QUOTATION_NO =#{st_quotation_no}
	AND QUOTATION_SEQ = #{st_quotation_seq}
	AND REVISION = #{st_revision}
	AND STATUS = 'C'


/*commonPopup.commonNegoLogInfoPop*/
	SELECT
		A.NEGO_SEQ||'차' AS NEGO_SEQ
		,TO_CHAR(A.NEGO_DATE,'YYYY.MM.DD') AS NEGO_DATE
		,A.NEGO_PRICE AS NEGO_PRICE
		,A.BTOA_NEGO_PRICE AS BTOA_NEGO_PRICE
		,A.BTOA_NEGO_REMARK AS BTOA_NEGO_REMARK
	FROM BNTNEGOHISTORY A
	WHERE A.BUYER = #{st_buyer}
	AND A.QUOTATION_NO =#{st_quotation_no}
	AND A.QUOTATION_SEQ = #{st_quotation_seq}
	AND A.REVISION = #{st_revision}
	ORDER BY A.NEGO_SEQ


