SELECT CODE, --[0] TEXT2 --[1] ,TEXT1 --[1] FROM ICOMCOD2 WHERE TYPE = 'C012' AND COMPANY_CODE = #{com_code} AND CODE LIKE '%'||#{del_code}||'%' AND (TEXT1 LIKE '%'||#{del_name}||'%' OR TEXT2 LIKE '%'||#{del_name}||'%' )
