/*commonPopup.getComCodeList*/ SELECT CM.COM_CODE AS COM_CODE, CM.COM_NAME_LOC AS COM_NAME_LOC, CM.IRS_NO AS IRS_NO, CM.CEO_NAME_LOC AS CEO_NAME_LOC, DECODE(CM.BUSINESS_COND,'M','운영사','B','고객사','협력사') AS BUSINESS_COND, (SELECT DECODE(COUNT(A.SLG_ID), 0, 'N', 'Y') FROM BNTSLGDEF A, BNTSLGIMP B WHERE A.SLG_ID = B.SLG_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN A.OPEN_DATE AND A.CLOSE_DATE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN B.OPEN_DATE AND B.CLOSE_DATE AND B.COM_CODE = CM.COM_CODE AND A.SLG_ID = 'P01-1012-01') AS P01_1012_01_YN FROM ICOMCMPY CM WHERE CM.STATUS IN ('C', 'R') AND TRIM(CM.CLOSE_DATE) IS NULL AND CM.IRS_NO = #{h_irs_no}
AND CM.BUSINESS_COND = #{h_business_cond}
UNION SELECT CM.COM_CODE AS COM_CODE, CM.COM_NAME_LOC AS COM_NAME_LOC, CM.IRS_NO AS IRS_NO, CM.CEO_NAME_LOC AS CEO_NAME_LOC, DECODE(CM.BUSINESS_COND,'M','운영사','B','고객사','협력사') AS BUSINESS_COND, (SELECT DECODE(COUNT(A.SLG_ID), 0, 'N', 'Y') FROM BNTSLGDEF A, BNTSLGIMP B WHERE A.SLG_ID = B.SLG_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN A.OPEN_DATE AND A.CLOSE_DATE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN B.OPEN_DATE AND B.CLOSE_DATE AND B.COM_CODE = CM.COM_CODE AND A.SLG_ID = 'P01-1012-01') AS P01_1012_01_YN FROM ICOMCMPY CM WHERE CM.STATUS IN ('C', 'R') AND TRIM(CM.CLOSE_DATE) IS NULL AND CM.IRS_NO IN ( SELECT CODE2 FROM ICOMCOD3 WHERE TYPE = 'IRSB' AND CODE1 = #{h_irs_no} AND FLAG = 'Y' )
AND CM.BUSINESS_COND = #{h_business_cond}

/* selectGetUserList */ SELECT USER_ID ,LEGACY_USER_ID ,USER_NAME ,EMAIL ,PHONE_NUMBER ,MOBILE_PHONE ,COM_NAME ,DEPT_TEXT ,COM_CODE ,REG_DATE FROM ( SELECT L.USER_ID AS USER_ID ,L.LEGACY_USER_ID ,L.USER_NAME_LOC AS USER_NAME ,L.EMAIL ,L.PHONE_NUMBER ,L.MOBILE_PHONE ,C.COM_NAME_LOC AS COM_NAME ,(SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = L.COM_CODE AND TYPE = 'C001' AND CODE = DEPARTMENT) AS DEPT_TEXT ,L.COM_CODE AS COM_CODE ,REG_DATE FROM ICOMLUSR L, ICOMCMPY C WHERE L.COM_CODE = C.COM_CODE AND C.STATUS IN ('C','R') AND (L.STATUS IN ('C','R') OR (L.USER_TYPE = 'U' AND L.CHANGE_USER_TYPE = 'A' AND L.STATUS = 'A')) AND (C.COM_TYPE IS NULL OR C.COM_TYPE <> 'X') ) WHERE 1=1
AND COM_CODE = #{st_buyer}
AND LEGACY_USER_ID = #{st_legacy_user_id}
AND USER_NAME = #{st_user_name}
ORDER BY REG_DATE DESC

/*commonPopup.kepIndTypePop*/ SELECT CODE, TEXT1 FROM ICOMCOD1 WHERE TYPE = 'CP13' AND FLAG = 'Y'
AND TEXT1 LIKE '%'||#{ind_name}||'%'
ORDER BY VALUE1

/*commonPopup.masterMdCmCmsItemMngrSelPop*/ SELECT U.USER_ID AS KEP_USER_ID /* 반환 USER_ID 키 */ , U.USER_NAME_LOC AS KEP_USER_NAME /* 담당자명 */ , U.LEGACY_USER_ID AS KEP_USER_NO /* 사번(표시용) */ , D.TEXT1 AS KEP_DEPT_NAME /* 팀명 */ FROM ICOMLUSR U , ICOMCOD1 D WHERE D.TYPE = 'SOURDEPT' /* 구매부서(SOURDEPT) 소속만 조회 대상 */ AND D.FLAG = 'Y' AND D.CODE NOT IN ('130','138') /* 구매본부, 구매기획팀 제외 (팀명 드롭다운과 동일) */ AND D.CODE = U.DEPARTMENT AND U.COM_CODE = 'KRKORE0001' /* 본사(KeP) 사용자만 */ AND U.STATUS IN ('C','R') /* 사무용품 전용 계정 제외 : 같은 사람이 O 접두 계정(OKEP…)으로 한 벌 더 있어 목록에 중복으로 뜬다. ⚠ NVL 필수 — 정상 계정은 OFFICE_YN 이 NULL 이라 OFFICE_YN != 'Y' 로 쓰면 전부 걸러져 0건이 된다. */ AND NVL(U.OFFICE_YN,'N') != 'Y'
AND U.DEPARTMENT = #{kep_dept}
AND UPPER(U.USER_NAME_LOC) LIKE '%'||UPPER(#{kep_user_name})||'%'
ORDER BY D.VALUE1, U.USER_NAME_LOC, U.USER_ID


