/*commonPopup.getKepManagerB_v2*/
	SELECT USER_NAME_LOC,PHONE_NUMBER FROM ICOMLUSR
	WHERE USER_ID = (
		SELECT KEP_USER_ID FROM MIS_BUYER_MNG
		WHERE BUYER = #{comCode}
		AND PRIORITY = 'Y'
		AND STATUS = 'C'
		AND YEAR = TO_CHAR(SYSDATE,'YYYY')
	)


/*commonPopup.getKepManagerS_v2*/
	SELECT USER_NAME_LOC,PHONE_NUMBER FROM ICOMLUSR
	WHERE USER_ID = (
		SELECT TEXT1 FROM ICOMCOD3
		WHERE TYPE = 'CMSM'
		AND CODE1 = (
			SELECT SG_ID FROM SUPLINFO2
			WHERE SUPPLIER = #{comCode}
		)
		AND TEXT2 = 'Y'
	)
